                let out = if out.body.len() > BODY_CAP {
                    log::warn!("remote: {} {} is over the body cap", key.kind(), key.id());
                    RemoteReply {
                        status: 500,
                        body: self.error_json("too_large", "the reply is over the body cap"),
                        authenticated: true,
                    }
                } else {
                    out
